describe('Task Creation Form', () => {
  beforeEach(() => {
    cy.visit('/tasks');
    cy.get('[data-testid="create-task-btn"]').click();
  });

  it('should successfully create a new task with valid form data', () => {
    const taskData = {
      title: 'Complete project documentation',
      description: 'Write comprehensive documentation for the new API',
      priority: 'High',
      dueDate: '2024-12-31',
      assignee: 'John Doe',
      tags: ['documentation', 'api']
    };

    cy.get('[data-testid="task-title-input"]')
      .should('be.visible')
      .clear()
      .type(taskData.title);

    cy.get('[data-testid="task-description-textarea"]')
      .should('be.visible')
      .clear()
      .type(taskData.description);

    cy.get('[data-testid="task-priority-select"]')
      .should('be.visible')
      .select(taskData.priority);

    cy.get('[data-testid="task-due-date-input"]')
      .should('be.visible')
      .type(taskData.dueDate);

    cy.get('[data-testid="task-assignee-dropdown"]')
      .should('be.visible')
      .click();

    cy.get('[data-testid="assignee-option"]')
      .contains(taskData.assignee)
      .click();

    taskData.tags.forEach(tag => {
      cy.get('[data-testid="task-tags-input"]')
        .type(tag);
      cy.get('[data-testid="tag-suggestion"]')
        .first()
        .click();
    });

    cy.get('[data-testid="save-task-btn"]')
      .should('be.enabled')
      .click();

    cy.get('[data-testid="success-toast"]')
      .should('be.visible')
      .and('contain', 'Task created successfully');

    cy.url().should('include', '/tasks');

    cy.get('[data-testid="task-list"]')
      .should('contain', taskData.title);

    cy.get('[data-testid="task-item"]')
      .contains(taskData.title)
      .parent()
      .should('contain', taskData.priority)
      .and('contain', taskData.dueDate);
  });

  it('should display validation errors when required fields are empty', () => {
    cy.get('[data-testid="save-task-btn"]')
      .should('be.disabled');

    cy.get('[data-testid="task-title-input"]')
      .focus()
      .blur();

    cy.get('[data-testid="title-error-message"]')
      .should('be.visible')
      .and('contain', 'Title is required');

    cy.get('[data-testid="task-description-textarea"]')
      .focus()
      .blur();

    cy.get('[data-testid="description-error-message"]')
      .should('be.visible')
      .and('contain', 'Description is required');

    cy.get('[data-testid="task-due-date-input"]')
      .focus()
      .blur();

    cy.get('[data-testid="due-date-error-message"]')
      .should('be.visible')
      .and('contain', 'Due date is required');

    cy.get('[data-testid="save-task-btn"]')
      .should('be.disabled');
  });

  it('should handle form submission with special characters and long text', () => {
    const specialCharTitle = 'Task: Test & Verify @2024 #urgent!';
    const longDescription = 'A'.repeat(500);

    cy.get('[data-testid="task-title-input"]')
      .type(specialCharTitle);

    cy.get('[data-testid="task-description-textarea"]')
      .type(longDescription);

    cy.get('[data-testid="task-priority-select"]')
      .select('Medium');

    cy.get('[data-testid="task-due-date-input"]')
      .type('2024-12-25');

    cy.get('[data-testid="task-assignee-dropdown"]')
      .click();

    cy.get('[data-testid="assignee-option"]')
      .first()
      .click();

    cy.get('[data-testid="save-task-btn"]')
      .click();

    cy.get('[data-testid="success-toast"]')
      .should('be.visible');

    cy.get('[data-testid="task-item"]')
      .contains(specialCharTitle)
      .should('exist');
  });

  it('should clear form and reset to initial state when cancel is clicked', () => {
    cy.get('[data-testid="task-title-input"]')
      .type('Test Task');

    cy.get('[data-testid="task-description-textarea"]')
      .type('Test Description');

    cy.get('[data-testid="cancel-task-btn"]')
      .click();

    cy.get('[data-testid="task-form"]')
      .should('not.exist');

    cy.url().should('include', '/tasks');
  });

  it('should prevent duplicate task creation with rapid successive clicks', () => {
    cy.get('[data-testid="task-title-input"]')
      .type('Unique Task Title');

    cy.get('[data-testid="task-description-textarea"]')
      .type('Task Description');

    cy.get('[data-testid="task-priority-select"]')
      .select('Low');

    cy.get('[data-testid="task-due-date-input"]')
      .type('2024-12-20');

    cy.get('[data-testid="task-assignee-dropdown"]')
      .click();

    cy.get('[data-testid="assignee-option"]')
      .first()
      .click();

    cy.get('[data-testid="save-task-btn"]')
      .click()
      .click()
      .click();

    cy.get('[data-testid="success-toast"]')
      .should('have.length', 1);

    cy.get('[data-testid="task-item"]')
      .contains('Unique Task Title')
      .should('have.length', 1);
  });
});
